package com.jbrempresa.backend.repository;import java.time.LocalDateTime;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import com.jbrempresa.backend.entity.ReservaRecurso;
public interface ReservaRecursoRepository extends JpaRepository<ReservaRecurso,Long>{List<ReservaRecurso> findByEmpIdAndResIdAndRerActTrue(Long empId,Long resId);void deleteByEmpIdAndResId(Long empId,Long resId);@Query("select count(rr) from ReservaRecurso rr join Reserva r on r.resId=rr.resId where rr.empId=:cli and rr.ragId=:rag and rr.rerAct=true and r.resAct=true and r.resEst not in ('CANCELADA','AUSENCIA') and (:excluir is null or r.resId<>:excluir) and rr.rerIniOcu<:fin and rr.rerFinOcu>:inicio")long contarSolapamientos(@Param("cli")Long cli,@Param("rag")Long rag,@Param("inicio")LocalDateTime inicio,@Param("fin")LocalDateTime fin,@Param("excluir")Long excluir);}
